<?php

declare(strict_types=1);

namespace DoorLock;

/**
 * Application configuration.
 *
 * Precedence (lowest to highest):
 *   1. Hard-coded safe defaults (never contain secrets).
 *   2. config/config.local.php (generated by bin/install.php, never committed).
 *   3. DOORLOCK_* environment variables (useful for containers and tests).
 */
final class Config
{
    /** @var array<string,mixed> */
    private static array $values = [];

    private static bool $loaded = false;

    /** @return array<string,mixed> */
    public static function defaults(): array
    {
        return [
            'app_env' => 'production',
            'app_timezone' => 'Asia/Tehran',
            'app_key' => null,
            'app_url' => 'http://localhost',
            'trust_proxy' => false,
            'allowed_origins' => [],
            'max_body_bytes' => 65536,
            'log_dir' => 'storage/logs',
            'log_level' => 'info',
            'session' => [
                'name' => 'doorlock_sid',
                'save_path' => null,
                'idle_timeout' => 1800,
                'absolute_timeout' => 28800,
                'cookie_secure' => 'auto',
            ],
            'db' => [
                'driver' => 'mysql',
                'host' => '127.0.0.1',
                'port' => 3306,
                'name' => 'doorlock',
                'user' => 'doorlock',
                'password' => null,
                'sqlite_path' => null,
                'dsn' => null,
            ],
            'security' => [
                'login_max_attempts' => 5,
                'login_ip_max_attempts' => 30,
                'login_window' => 900,
                'login_lockout' => 900,
                'device_clock_skew' => 120,
                'device_nonce_ttl' => 600,
                'device_rate_limit_per_minute' => 60,
                'require_https_for_devices' => true,
                'allow_insecure_device_http' => false,
                'require_https_for_admin' => false,
                'min_password_length' => 12,
                'max_grant_days' => 90,
            ],
            'limits' => [
                'default_page_size' => 50,
                'max_page_size' => 200,
                'max_export_rows' => 10000,
                'max_schedules_per_pair' => 50,
                'max_cards_per_person' => 10,
            ],
            'retention' => [
                'access_log_days' => 365,
                'audit_log_days' => 730,
                'login_attempt_days' => 30,
                'app_log_days' => 30,
            ],
        ];
    }

    /** @param array<string,mixed> $overrides */
    public static function load(?string $localConfigPath = null, array $overrides = []): void
    {
        $values = self::defaults();

        if ($localConfigPath !== null && is_file($localConfigPath)) {
            /** @var mixed $local */
            $local = require $localConfigPath;
            if (!is_array($local)) {
                throw new ConfigError('config/config.local.php must return an array.');
            }
            $values = self::merge($values, $local);
        }

        $values = self::merge($values, $overrides);
        $values = self::merge($values, self::envOverrides());

        self::$values = $values;
        self::$loaded = true;
        self::validate();
    }

    public static function isLoaded(): bool
    {
        return self::$loaded;
    }

    public static function get(string $path, mixed $default = null): mixed
    {
        $cursor = self::$values;
        foreach (explode('.', $path) as $segment) {
            if (!is_array($cursor) || !array_key_exists($segment, $cursor)) {
                return $default;
            }
            $cursor = $cursor[$segment];
        }
        return $cursor;
    }

    public static function require(string $path): mixed
    {
        $value = self::get($path);
        if ($value === null || $value === '') {
            throw new ConfigError("Required configuration value '{$path}' is missing.");
        }
        return $value;
    }

    public static function bool(string $path, bool $default = false): bool
    {
        $value = self::get($path, $default);
        return filter_var($value, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE) ?? $default;
    }

    public static function int(string $path, int $default = 0): int
    {
        $value = self::get($path, $default);
        if (is_int($value)) {
            return $value;
        }
        if (is_string($value) && preg_match('/^-?\d+$/', $value) === 1) {
            return (int) $value;
        }
        return $default;
    }

    /** Raw 32+ byte application key used to derive device HMAC keys. */
    public static function appKeyRaw(): string
    {
        $encoded = (string) self::require('app_key');
        $raw = null;
        if (str_starts_with($encoded, 'base64:')) {
            $decoded = base64_decode(substr($encoded, 7), true);
            if ($decoded !== false) {
                $raw = $decoded;
            }
        } elseif (preg_match('/^[0-9a-fA-F]{64,}$/', $encoded) === 1 && strlen($encoded) % 2 === 0) {
            $decoded = hex2bin($encoded);
            if ($decoded !== false) {
                $raw = $decoded;
            }
        }
        if ($raw === null || strlen($raw) < 32) {
            throw new ConfigError('app_key must be 64+ hex characters or base64: of at least 32 bytes.');
        }
        return $raw;
    }

    public static function isProduction(): bool
    {
        return self::get('app_env') === 'production';
    }

    public static function basePath(): string
    {
        return \DOORLOCK_ROOT;
    }

    /** @param array<string,mixed> $base @param array<string,mixed> $extra */
    private static function merge(array $base, array $extra): array
    {
        foreach ($extra as $key => $value) {
            if (is_array($value) && isset($base[$key]) && is_array($base[$key])) {
                $base[$key] = self::merge($base[$key], $value);
            } else {
                $base[$key] = $value;
            }
        }
        return $base;
    }

    /** @return array<string,mixed> */
    private static function envOverrides(): array
    {
        $map = [
            'DOORLOCK_ENV' => ['app_env', 'string'],
            'DOORLOCK_TIMEZONE' => ['app_timezone', 'string'],
            'DOORLOCK_APP_KEY' => ['app_key', 'string'],
            'DOORLOCK_APP_URL' => ['app_url', 'string'],
            'DOORLOCK_TRUST_PROXY' => ['trust_proxy', 'bool'],
            'DOORLOCK_ALLOWED_ORIGINS' => ['allowed_origins', 'csv'],
            'DOORLOCK_MAX_BODY_BYTES' => ['max_body_bytes', 'int'],
            'DOORLOCK_LOG_DIR' => ['log_dir', 'string'],
            'DOORLOCK_LOG_LEVEL' => ['log_level', 'string'],
            'DOORLOCK_SESSION_NAME' => ['session.name', 'string'],
            'DOORLOCK_SESSION_SAVE_PATH' => ['session.save_path', 'string'],
            'DOORLOCK_SESSION_IDLE_TIMEOUT' => ['session.idle_timeout', 'int'],
            'DOORLOCK_SESSION_ABSOLUTE_TIMEOUT' => ['session.absolute_timeout', 'int'],
            'DOORLOCK_SESSION_COOKIE_SECURE' => ['session.cookie_secure', 'string'],
            'DOORLOCK_DB_DRIVER' => ['db.driver', 'string'],
            'DOORLOCK_DB_HOST' => ['db.host', 'string'],
            'DOORLOCK_DB_PORT' => ['db.port', 'int'],
            'DOORLOCK_DB_NAME' => ['db.name', 'string'],
            'DOORLOCK_DB_USER' => ['db.user', 'string'],
            'DOORLOCK_DB_PASSWORD' => ['db.password', 'string'],
            'DOORLOCK_DB_SQLITE_PATH' => ['db.sqlite_path', 'string'],
            'DOORLOCK_DB_DSN' => ['db.dsn', 'string'],
            'DOORLOCK_LOGIN_MAX_ATTEMPTS' => ['security.login_max_attempts', 'int'],
            'DOORLOCK_LOGIN_WINDOW' => ['security.login_window', 'int'],
            'DOORLOCK_LOGIN_LOCKOUT' => ['security.login_lockout', 'int'],
            'DOORLOCK_DEVICE_CLOCK_SKEW' => ['security.device_clock_skew', 'int'],
            'DOORLOCK_DEVICE_NONCE_TTL' => ['security.device_nonce_ttl', 'int'],
            'DOORLOCK_DEVICE_RATE_LIMIT' => ['security.device_rate_limit_per_minute', 'int'],
            'DOORLOCK_REQUIRE_HTTPS_FOR_DEVICES' => ['security.require_https_for_devices', 'bool'],
            'DOORLOCK_ALLOW_INSECURE_DEVICE_HTTP' => ['security.allow_insecure_device_http', 'bool'],
            'DOORLOCK_REQUIRE_HTTPS_FOR_ADMIN' => ['security.require_https_for_admin', 'bool'],
            'DOORLOCK_MIN_PASSWORD_LENGTH' => ['security.min_password_length', 'int'],
            'DOORLOCK_MAX_GRANT_DAYS' => ['security.max_grant_days', 'int'],
        ];

        $overrides = [];
        foreach ($map as $envName => [$path, $type]) {
            $raw = getenv($envName);
            if (($raw === false || $raw === '')
                && (isset($_SERVER[$envName]) || isset($_ENV[$envName]))) {
                $raw = $_SERVER[$envName] ?? $_ENV[$envName];
            }
            if ($raw === false || $raw === '' || $raw === null) {
                continue;
            }
            $value = match ($type) {
                'bool' => filter_var($raw, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE) ?? false,
                'int' => (int) $raw,
                'csv' => array_values(array_filter(array_map('trim', explode(',', $raw)), static fn ($v) => $v !== '')),
                default => $raw,
            };
            self::setPath($overrides, $path, $value);
        }
        return $overrides;
    }

    /** @param array<string,mixed> $target */
    private static function setPath(array &$target, string $path, mixed $value): void
    {
        $segments = explode('.', $path);
        $cursor = &$target;
        foreach ($segments as $index => $segment) {
            if ($index === count($segments) - 1) {
                $cursor[$segment] = $value;
            } else {
                if (!isset($cursor[$segment]) || !is_array($cursor[$segment])) {
                    $cursor[$segment] = [];
                }
                $cursor = &$cursor[$segment];
            }
        }
    }

    private static function validate(): void
    {
        $env = (string) self::get('app_env');
        if (!in_array($env, ['production', 'staging', 'testing', 'development'], true)) {
            throw new ConfigError('app_env must be one of production, staging, testing, development.');
        }
        $tz = (string) self::get('app_timezone');
        try {
            new \DateTimeZone($tz);
        } catch (\Throwable) {
            throw new ConfigError('app_timezone is not a valid IANA timezone identifier.');
        }
        $driver = (string) self::get('db.driver');
        if (!in_array($driver, ['mysql', 'sqlite'], true)) {
            throw new ConfigError("Unsupported database driver '{$driver}'. Use mysql (production) or sqlite (development/tests).");
        }
        if ($driver === 'sqlite') {
            if (self::get('db.sqlite_path') === null && self::get('db.dsn') === null) {
                throw new ConfigError('SQLite requires db.sqlite_path or db.dsn.');
            }
        } else {
            foreach (['db.host', 'db.name', 'db.user'] as $required) {
                if (self::get($required) === null || self::get($required) === '') {
                    throw new ConfigError("MySQL configuration '{$required}' is required.");
                }
            }
        }
        if (self::get('app_key') !== null) {
            self::appKeyRaw(); // validates format
        }
        $idle = self::int('session.idle_timeout');
        $absolute = self::int('session.absolute_timeout');
        if ($idle < 60 || $absolute < $idle) {
            throw new ConfigError('Session timeouts are invalid (absolute_timeout must be >= idle_timeout >= 60).');
        }
        if (self::int('max_body_bytes') < 1024 || self::int('max_body_bytes') > 1048576) {
            throw new ConfigError('max_body_bytes must be between 1024 and 1048576.');
        }
        $secure = (string) self::get('session.cookie_secure');
        if (!in_array($secure, ['auto', '0', '1', 'true', 'false'], true)) {
            throw new ConfigError("session.cookie_secure must be 'auto', '0' or '1'.");
        }
    }

    /** Merge additional values at runtime (installer, migrations, tests). */
    public static function override(array $values): void
    {
        self::$values = self::merge(self::$values, $values);
        self::$loaded = true;
        self::validate();
    }

    /** Test helper: replace all configuration values. */
    public static function resetForTests(?array $values = null): void
    {
        self::$values = $values ?? [];
        self::$loaded = $values !== null;
        if ($values !== null) {
            self::validate();
        }
    }
}
